const $=id=>document.getElementById(id),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n),form=$('form');
async function labQuote(carat,shape){const r=await fetch('https://veyaradiamonds.com/data/lab-grown-diamond-price-benchmarks.json');if(!r.ok)throw Error('The verified lab-grown source is unavailable.');const p=await r.json(),latest=[...p.snapshots].sort((a,b)=>b.date.localeCompare(a.date))[0],name=shape[0].toUpperCase()+shape.slice(1),rows=latest.cells.filter(x=>x.shape===name);const cell=rows.find(x=>carat>=x.min_carat&&carat<x.max_carat)||rows.sort((a,b)=>Math.abs(a.min_carat-carat)-Math.abs(b.min_carat-carat))[0];if(!cell)throw Error('No lab-grown benchmark is published for that shape.');return {provider:'Veyara Diamonds',source_url:'https://veyaradiamonds.com/lab-grown-diamond-price-benchmarks',updated:latest.date,specification:latest.spec,per_carat:cell.median_per_carat_usd,total:cell.median_total_usd,low:cell.p25_total_usd,high:cell.p75_total_usd,count:cell.count,note:'Listed-price benchmark from one disclosed public inventory dataset; not an appraisal or guaranteed quote.'};}
async function naturalQuote(carat,shape,colour,clarity){const api=`https://caratatlas.com/api/v1/price?carat=${carat}&colour=${colour}&clarity=${clarity}&shape=${shape}`,r=await fetch(api,{headers:{Accept:'application/json'}});if(r.ok){const b=await r.json();return {...b,provider:'CaratAtlas / OpenFacet',source_url:'https://caratatlas.com/api',count:b.comparable_count||0,note:'Natural GIA benchmark from the public CaratAtlas/OpenFacet feed; not an appraisal or guaranteed quote.'};}if(shape!=='round')throw Error('The live natural-diamond source is temporarily unavailable for fancy shapes. Try round, or use a verified supplier listing.');const m=await (await fetch('https://data.openfacet.net/matrix.json')).json(),ci=['D','E','F','G','H','I','J','K','L','M'].indexOf(colour),qi=m.c.indexOf(clarity),anchors=Object.keys(m.l).map(Number).sort((a,b)=>a-b),usable=anchors.filter(a=>m.l[a][ci*m.c.length+qi]!=null),lo=usable.filter(a=>a<=carat).pop()??usable[0],hi=usable.find(a=>a>=carat)??usable.at(-1),lv=m.l[lo][ci*m.c.length+qi],hv=m.l[hi][ci*m.c.length+qi],t=lo===hi?0:(carat-lo)/(hi-lo),per_carat=Math.round(Math.exp(lv+(hv-lv)*t)*100)/100;return {provider:'OpenFacet fallback',source_url:'https://openfacet.net/en/api-docs/',updated:m.ts||new Date().toISOString(),per_carat,total:per_carat*carat,low:per_carat*carat,high:per_carat*carat,count:0,note:'Round natural GIA benchmark from OpenFacet public matrix; not an appraisal or retail quote.'};}
form.addEventListener('submit',async e=>{e.preventDefault();$('status').textContent='Checking verified market data…';$('result').hidden=true;const category=$('category').value,carat=Number($('carat').value),shape=$('shape').value,colour=$('colour').value,clarity=$('clarity').value;try{const b=category==='lab'?await labQuote(carat,shape):await naturalQuote(carat,shape,colour,clarity);$('status').textContent='';$('result').innerHTML=`<div class="metric"><span>Benchmark / ct</span><strong>${money(b.per_carat)}</strong></div><div class="metric"><span>Total reference</span><strong>${money(b.total)}</strong></div><div class="metric"><span>Observed range</span><strong>${money(b.low)}–${money(b.high)}</strong></div><div class="metric"><span>${category==='lab'?'Comparable listings':'Market type'}</span><strong>${category==='lab'?Number(b.count||0).toLocaleString():'Benchmark'}</strong></div><p class="detail"><strong>${b.provider}</strong> · ${b.specification||''} · Updated ${new Date(b.updated).toLocaleDateString()}<br>${b.note}<br><a href="${b.source_url}" target="_blank" rel="noopener">Open source methodology ↗</a></p>`;$('result').hidden=false}catch(err){$('status').textContent=err.message+' Record a supplier listing as the verified source when you need an exact stone-level price.'}});
